  // os.walk fixture (same tree CPython walked); entries are order-normalised for the paste,
  // and the top's order is pinned to the directory-read order separately.
  const T = path.join(tmp, "walk");
  for (const p of ["a/b", "c/d", "e"]) fs.mkdirSync(path.join(T, p), { recursive: true });
  for (const p of ["f.txt", "a/g", "a/b/h", "c/d/i", "e/j"]) fs.writeFileSync(path.join(T, p), "");
  fs.symlinkSync(path.join(T, "a"), path.join(T, "link"));
  fs.symlinkSync(path.join(T, "nowhere"), path.join(T, "broken"));
  const norm = (rows: [string, string[], string[]][]): unknown =>
    rows
      .map(([dp, dn, fn]) => [
        dp.replace(T, "<T>"),
        [...dn].sort(by_code_point),
        [...fn].sort(by_code_point),
      ])
      .sort((x, y) => by_code_point(x[0] as string, y[0] as string));
  fs.chmodSync(path.join(T, "e"), 0);
  const pruned: [string, string[], string[]][] = [];
  try {
    for (const [dp, dn, fn] of os_walk(T)) {
      if (dn.includes("c")) dn.splice(dn.indexOf("c"), 1);
      pruned.push([dp, [...dn], fn]);
    }
  } finally {
    fs.chmodSync(path.join(T, "e"), 0o755);
  }
  check("os_walk pruned, unreadable skipped, symlink not descended", norm(pruned), [
    ["<T>", ["a", "e", "link"], ["broken", "f.txt"]],
    ["<T>/a", ["b"], ["g"]],
    ["<T>/a/b", [], ["h"]],
  ]);
  check("os_walk(top/)", norm([...os_walk(T + "/")]), [
    ["<T>/", ["a", "c", "e", "link"], ["broken", "f.txt"]],
    ["<T>/a", ["b"], ["g"]],
    ["<T>/a/b", [], ["h"]],
    ["<T>/c", ["d"], []],
    ["<T>/c/d", [], ["i"]],
    ["<T>/e", [], ["j"]],
  ]);
  const order = fs.readdirSync(T, { withFileTypes: true });
  const [, top_dirs, top_files] = os_walk(T).next().value!;
  check(
    "os_walk keeps directory-read order",
    [top_dirs, top_files],
    [
      order.filter((e) => e.isDirectory() || e.name === "link").map((e) => e.name),
      order.filter((e) => !e.isDirectory() && e.name !== "link").map((e) => e.name),
    ],
  );

